struct policy { int (*decide)(const struct subject *, enum action, const struct resource *); };
static int guard(const struct policy *p, const struct subject *s,
                 enum action a, const struct resource *r) {
    if (!p->decide(s, a, r)) { audit_denied(s, a, r); return -EPERM; }  /* deny by default */
    return 0;
}
